import type { LeaderboardEntry, LeaderboardGenerationOptions } from './types';

const FIRST_NAMES = [
  'Nova', 'Milo', 'Luna', 'Kai', 'Zara', 'Theo', 'Iris', 'Nico', 'Maya', 'Finn', 'Juno', 'Ezra',
  'Aria', 'Remy', 'Cleo', 'Otto', 'Nia', 'Leo', 'Mira', 'Axel', 'Skye', 'Noah', 'Vera', 'Hugo',
];
const HANDLES = [
  'PuttPilot', 'BankShot', 'NeonAce', 'SlopeFox', 'CupHunter', 'OrbitPutt', 'GreenByte', 'PinSeeker',
  'BounceLab', 'Paradox', 'CurveCat', 'TinyCannon', 'FlagRunner', 'SpinDoctor', 'RampRider', 'MoonPutt',
];
const COUNTRIES = ['US', 'GB', 'DE', 'FR', 'ES', 'IT', 'NL', 'SE', 'FI', 'PL', 'BR', 'CA', 'JP', 'KR', 'AU', 'NZ', 'CZ', 'AT'];
const BALL_STYLES = ['classic', 'neon', 'comet', 'carbon', 'sunset', 'ocean', 'mint', 'plasma'];

function hashSeed(seed: number | string): number {
  if (typeof seed === 'number') return seed >>> 0;
  let hash = 2166136261;
  for (let i = 0; i < seed.length; i += 1) {
    hash ^= seed.charCodeAt(i);
    hash = Math.imul(hash, 16777619);
  }
  return hash >>> 0;
}

function mulberry32(seed: number): () => number {
  let state = seed >>> 0;
  return () => {
    state = (state + 0x6d2b79f5) | 0;
    let value = Math.imul(state ^ (state >>> 15), 1 | state);
    value = (value + Math.imul(value ^ (value >>> 7), 61 | value)) ^ value;
    return ((value ^ (value >>> 14)) >>> 0) / 4294967296;
  };
}

function intBetween(random: () => number, min: number, max: number): number {
  return Math.floor(random() * (max - min + 1)) + min;
}

function round(value: number, digits = 2): number {
  const scale = 10 ** digits;
  return Math.round(value * scale) / scale;
}

export function generateAILeaderboard(options: LeaderboardGenerationOptions = {}): LeaderboardEntry[] {
  const count = Math.max(0, Math.floor(options.count ?? 64));
  const seed = hashSeed(options.seed ?? 'crazy-putt-arena-leaderboard-v1');
  const random = mulberry32(seed);
  const entries: LeaderboardEntry[] = [];

  for (let index = 0; index < count; index += 1) {
    const skill = 0.25 + random() * 0.75;
    const matchesPlayed = intBetween(random, 24, 420);
    const winChance = 0.035 + skill * 0.34;
    const wins = Math.min(matchesPlayed, Math.round(matchesPlayed * winChance * (0.78 + random() * 0.44)));
    const podiums = Math.min(matchesPlayed, Math.max(wins, Math.round(matchesPlayed * (winChance + 0.12 + skill * 0.18))));
    const holesPlayed = matchesPlayed * intBetween(random, 6, 12);
    const holesInOne = Math.round(holesPlayed * (0.003 + skill * 0.032) * (0.8 + random() * 0.4));
    const averageStrokes = round(4.65 - skill * 1.85 + (random() - 0.5) * 0.34);
    const rating = Math.round(850 + skill * 1450 + (random() - 0.5) * 130);
    const first = FIRST_NAMES[index % FIRST_NAMES.length];
    const handle = HANDLES[(index * 7 + intBetween(random, 0, HANDLES.length - 1)) % HANDLES.length];

    entries.push({
      id: `ai-${seed.toString(16)}-${String(index + 1).padStart(3, '0')}`,
      displayName: `${first} ${handle}${index + 1}`,
      kind: 'bot',
      ballStyleId: BALL_STYLES[intBetween(random, 0, BALL_STYLES.length - 1)],
      rating,
      rank: 0,
      countryCode: COUNTRIES[intBetween(random, 0, COUNTRIES.length - 1)],
      stats: {
        matchesPlayed,
        wins,
        podiums,
        holesPlayed,
        holesInOne,
        averageStrokes,
        winRate: round(wins / matchesPlayed, 3),
      },
    });
  }

  return entries
    .sort((a, b) => b.rating - a.rating || b.stats.wins - a.stats.wins || a.displayName.localeCompare(b.displayName))
    .map((entry, index) => ({ ...entry, rank: index + 1 }));
}
