import type { LeaderboardEntry } from './types';

export interface LeaderboardViewOptions {
  title?: string;
  highlightPlayerId?: string;
  maxRows?: number;
}

function createCell(text: string, className?: string): HTMLTableCellElement {
  const cell = document.createElement('td');
  cell.textContent = text;
  if (className) cell.className = className;
  return cell;
}

export function renderLeaderboard(entries: readonly LeaderboardEntry[], options: LeaderboardViewOptions = {}): HTMLElement {
  const panel = document.createElement('section');
  panel.className = 'leaderboard';
  panel.setAttribute('aria-label', options.title ?? 'Global leaderboard');

  const heading = document.createElement('div');
  heading.className = 'leaderboard__heading';
  const title = document.createElement('h2');
  title.textContent = options.title ?? 'Global Leaderboard';
  const count = document.createElement('span');
  count.className = 'leaderboard__count';
  count.textContent = `${entries.length} players`;
  heading.append(title, count);
  panel.append(heading);

  const scroll = document.createElement('div');
  scroll.className = 'leaderboard__scroll';
  const table = document.createElement('table');
  table.className = 'leaderboard__table';
  const thead = document.createElement('thead');
  const headerRow = document.createElement('tr');
  for (const label of ['Rank', 'Player', 'Rating', 'Wins', 'Win %', 'Avg.']) {
    const th = document.createElement('th');
    th.scope = 'col';
    th.textContent = label;
    headerRow.append(th);
  }
  thead.append(headerRow);
  table.append(thead);

  const body = document.createElement('tbody');
  const visible = entries.slice(0, Math.max(0, options.maxRows ?? entries.length));
  for (const entry of visible) {
    const row = document.createElement('tr');
    row.dataset.playerId = entry.id;
    if (entry.id === options.highlightPlayerId) row.classList.add('leaderboard__row--highlight');
    row.append(
      createCell(`#${entry.rank}`, 'leaderboard__rank'),
      createCell(`${entry.countryCode}  ${entry.displayName}`, 'leaderboard__player'),
      createCell(entry.rating.toLocaleString(), 'leaderboard__rating'),
      createCell(`${entry.stats.wins}/${entry.stats.matchesPlayed}`),
      createCell(`${Math.round(entry.stats.winRate * 100)}%`),
      createCell(entry.stats.averageStrokes.toFixed(2)),
    );
    body.append(row);
  }
  table.append(body);
  scroll.append(table);
  panel.append(scroll);
  return panel;
}
