import { strict as assert } from 'node:assert';
import { test } from 'node:test';
import { generateAILeaderboard } from '../src/leaderboard/generator.ts';

test('generates 50+ deterministic AI leaderboard entries', () => {
  const first = generateAILeaderboard({ seed: 'arena-season-1', count: 64 });
  const second = generateAILeaderboard({ seed: 'arena-season-1', count: 64 });
  assert.equal(first.length, 64);
  assert.deepEqual(first, second);
  assert.equal(new Set(first.map((entry) => entry.id)).size, 64);
  assert.equal(new Set(first.map((entry) => entry.displayName)).size, 64);
});

test('entries satisfy profile and statistics invariants', () => {
  const entries = generateAILeaderboard({ seed: 42, count: 80 });
  entries.forEach((entry, index) => {
    assert.equal(entry.kind, 'bot');
    assert.equal(entry.rank, index + 1);
    assert.ok(entry.rating >= 800 && entry.rating <= 2400);
    assert.ok(entry.stats.wins <= entry.stats.podiums);
    assert.ok(entry.stats.podiums <= entry.stats.matchesPlayed);
    assert.ok(entry.stats.holesInOne <= entry.stats.holesPlayed);
    assert.ok(entry.stats.winRate >= 0 && entry.stats.winRate <= 1);
    if (index > 0) assert.ok(entries[index - 1].rating >= entry.rating);
  });
});
